cd /workspace/testbed && node -e "
const fs = require('fs');
const PizZip = require('pizzip');

const content = fs.readFileSync('docs/travel_summary.docx');
const zip = new PizZip(content);
let xml = zip.file('word/document.xml').asText();

// Update booking BK-B70889: empty route -> JFK → LHR, status -> confirmed/on schedule
const oldText = 'Booking BK-B70889 | user_59b22691 |  →  | business | Status: confirmed | \$1180';
const newText = 'Booking BK-B70889 | user_59b22691 | JFK → LHR | business | Status: confirmed/on schedule | \$1180';

if (!xml.includes(oldText)) {
  console.error('ERROR: Could not find the target text in the document');
  process.exit(1);
}

xml = xml.replace(oldText, newText);
zip.file('word/document.xml', xml);

const out = zip.generate({ type: 'nodebuffer' });
fs.writeFileSync('docs/travel_summary.docx', out);
console.log('Updated successfully');
"

